1	package checkpoint
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"log/slog"
8		"strconv"
9	
10		"github.com/go-git/go-git/v6"
11		"github.com/go-git/go-git/v6/plumbing"
12		"github.com/go-git/go-git/v6/plumbing/object"
13	
14		"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
15		"github.com/entireio/cli/cmd/entire/cli/logging"
16		"github.com/entireio/cli/cmd/entire/cli/validation"
17	)
18	
19	var (
20		_ PersistentStore = (*gitRefsStore)(nil)
21		_ AuthorReader    = (*gitRefsStore)(nil)
22		_ Writer          = (*gitRefsStore)(nil)
23	)
24	
25	// gitRefsStore is the git-backed persistent checkpoint store that keeps one ref
26	// per checkpoint at refs/entire/checkpoints/<shard>/<id>. Each ref points at a
27	// commit whose tree root IS that checkpoint's contents (metadata.json, 0/, 1/,
28	// tasks/…), so updates advance the ref and preserve per-checkpoint history. It
29	// shares the checkpoint-subtree machinery with the git-branch store via the
30	// embedded *treeWriter (anchored at basePath ""), differing only in where the
31	// subtree is committed: a per-checkpoint ref instead of the v1 branch.
32	type gitRefsStore struct {
33		*treeWriter
34	
35		blobFetcher BlobFetchFunc
36		refFetcher  RefFetchFunc
37	}
38	
39	// newGitRefsStore constructs the per-checkpoint-ref store for a repository.
40	func newGitRefsStore(repo *git.Repository) *gitRefsStore {
41		return &gitRefsStore{treeWriter: &treeWriter{repo: repo}}
42	}
43	
44	// SetBlobFetcher configures on-demand blob fetching for reads from ref trees.
45	func (s *gitRefsStore) SetBlobFetcher(f BlobFetchFunc) {
46		s.blobFetcher = f
47	}
48	
49	// SetRefFetcher configures on-demand fetching of a missing checkpoint ref (e.g.
50	// a checkpoint written on another machine). nil leaves reads local-only.
51	func (s *gitRefsStore) SetRefFetcher(f RefFetchFunc) {
52		s.refFetcher = f
53	}
54	
55	// Write dispatches a persistent write request to the matching ref operation,
56	// mirroring the git-branch store's Write.
57	func (s *gitRefsStore) Write(ctx context.Context, req WriteRequest) error {
58		switch r := req.(type) {
59		case Session:
60			return s.writeSession(ctx, WriteOptions(r))
61		case SessionTranscript:
62			return s.backfillTranscript(ctx, UpdateOptions(r))
63		case SessionSummary:
64			return s.backfillSummary(ctx, r.CheckpointID, r.Summary)
65		case CheckpointAttribution:
66			return s.backfillAttribution(ctx, r.CheckpointID, r.Attribution)
67		default:
68			return fmt.Errorf("checkpoint: unsupported write request %T", req)
69		}
70	}
71	
72	// refBase resolves a checkpoint ref's current tip commit (the parent for the
73	// next write) and subtree object (the checkpoint's current contents). A missing
74	// ref yields (ZeroHash, nil) so the next write becomes an orphan commit.
75	func (s *gitRefsStore) refBase(cid id.CheckpointID) (plumbing.Hash, *object.Tree, error) {
76		refName, err := RefName(cid)
77		if err != nil {
78			return plumbing.ZeroHash, nil, err
79		}
80		ref, err := s.repo.Reference(refName, true)
81		if errors.Is(err, plumbing.ErrReferenceNotFound) {
82			return plumbing.ZeroHash, nil, nil // no ref yet → new checkpoint (orphan)
83		}
84		if err != nil {
85			// A real lookup failure (IO/corruption), not an absent ref: surface it
86			// rather than silently starting a fresh orphan history over the ref.
87			return plumbing.ZeroHash, nil, fmt.Errorf("resolve checkpoint ref %s: %w", refName, err)
88		}
89		commit, err := s.repo.CommitObject(ref.Hash())
90		if err != nil {
91			return plumbing.ZeroHash, nil, fmt.Errorf("read checkpoint commit %s: %w", ref.Hash(), err)
92		}
93		tree, err := commit.Tree()
94		if err != nil {
95			return plumbing.ZeroHash, nil, fmt.Errorf("read checkpoint tree for %s: %w", cid, err)
96		}
97		return ref.Hash(), tree, nil
98	}
99	
100	// setRef points a checkpoint's ref at a new commit and records it for push.
101	// Enqueue is best-effort: a write that lands locally but fails to enqueue must
102	// not fail condensation. The ref is still local; only its remote sync is missed
103	// until a later write to the same checkpoint re-enqueues it.
104	func (s *gitRefsStore) setRef(ctx context.Context, cid id.CheckpointID, hash plumbing.Hash) error {
105		refName, err := RefName(cid)
106		if err != nil {
107			return err
108		}
109		if err := s.repo.Storer.SetReference(plumbing.NewHashReference(refName, hash)); err != nil {
110			return fmt.Errorf("set checkpoint ref %s to %s: %w", refName, hash, err)
111		}
112		s.enqueueForPush(ctx, refName)
113		return nil
114	}
115	
116	// enqueueForPush records refName in the push-discovery queue, logging (never
117	// returning) on failure so the local ref write still succeeds.
118	func (s *gitRefsStore) enqueueForPush(ctx context.Context, refName plumbing.ReferenceName) {
119		q, err := PushQueueForRepo(ctx, s.repo)
120		if err != nil {
121			logging.Warn(ctx, "checkpoint: resolve push queue failed; ref not enqueued",
122				slog.String("ref", refName.String()), slog.String("error", err.Error()))
123			return
124		}
125		if err := q.Enqueue(refName); err != nil {
126			logging.Warn(ctx, "checkpoint: enqueue checkpoint ref for push failed",
127				slog.String("ref", refName.String()), slog.String("error", err.Error()))
128		}
129	}
130	
131	func (s *gitRefsStore) writeSession(ctx context.Context, opts WriteOptions) error {
132		if opts.CheckpointID.IsEmpty() {
133			return errors.New("invalid checkpoint options: checkpoint ID is required")
134		}
135		if err := validation.ValidateSessionID(opts.SessionID); err != nil {
136			return fmt.Errorf("invalid checkpoint options: %w", err)
137		}
138		if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
139			return fmt.Errorf("invalid checkpoint options: %w", err)
140		}
141		if err := validation.ValidateAgentID(opts.AgentID); err != nil {
142			return fmt.Errorf("invalid checkpoint options: %w", err)
143		}
144	
145		parentHash, existing, err := s.refBase(opts.CheckpointID)
146		if err != nil {
147			return err
148		}
149	
150		checkpointSubtree, taskMetadataPath, err := s.applySessionWrite(ctx, opts, existing, "")
151		if err != nil {
152			return err
153		}
154	
155		commitMsg := s.buildCommitMessage(opts, taskMetadataPath)
156		commitHash, err := CreateCommit(ctx, s.repo, checkpointSubtree, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
157		if err != nil {
158			return err
159		}
160		return s.setRef(ctx, opts.CheckpointID, commitHash)
161	}
162	
163	func (s *gitRefsStore) backfillTranscript(ctx context.Context, opts UpdateOptions) error {
164		if opts.CheckpointID.IsEmpty() {
165			return errors.New("invalid update options: checkpoint ID is required")
166		}
167	
168		parentHash, existing, err := s.refBase(opts.CheckpointID)
169		if err != nil {
170			return err
171		}
172	
173		// applyTranscriptBackfill returns ErrCheckpointNotFound when the ref has no
174		// root summary yet (existing == nil → empty entries), matching the git-branch
175		// store's behavior for backfilling an unknown checkpoint.
176		checkpointSubtree, err := s.applyTranscriptBackfill(ctx, opts, existing, "")
177		if err != nil {
178			return err
179		}
180	
181		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
182		commitMsg := fmt.Sprintf("Finalize transcript for Checkpoint: %s", opts.CheckpointID)
183		commitHash, err := CreateCommit(ctx, s.repo, checkpointSubtree, parentHash, commitMsg, authorName, authorEmail)
184		if err != nil {
185			return err
186		}
187		return s.setRef(ctx, opts.CheckpointID, commitHash)
188	}
189	
190	func (s *gitRefsStore) backfillSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error {
191		if err := ctx.Err(); err != nil {
192			return err //nolint:wrapcheck // Propagating context cancellation
193		}
194	
195		parentHash, existing, err := s.refBase(checkpointID)
196		if err != nil {
197			return err
198		}
199	
200		checkpointSubtree, sessionID, err := s.applySummaryBackfill(ctx, existing, "", summary)
201		if err != nil {
202			return err
203		}
204	
205		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
206		commitMsg := fmt.Sprintf("Update summary for checkpoint %s (session: %s)", checkpointID, sessionID)
207		commitHash, err := CreateCommit(ctx, s.repo, checkpointSubtree, parentHash, commitMsg, authorName, authorEmail)
208		if err != nil {
209			return err
210		}
211		return s.setRef(ctx, checkpointID, commitHash)
212	}
213	
214	func (s *gitRefsStore) backfillAttribution(ctx context.Context, checkpointID id.CheckpointID, combinedAttribution *Attribution) error {
215		if err := ctx.Err(); err != nil {
216			return err //nolint:wrapcheck // Propagating context cancellation
217		}
218	
219		parentHash, existing, err := s.refBase(checkpointID)
220		if err != nil {
221			return err
222		}
223	
224		checkpointSubtree, err := s.applyAttributionBackfill(ctx, existing, "", combinedAttribution)
225		if err != nil {
226			return err
227		}
228	
229		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
230		commitMsg := fmt.Sprintf("Update checkpoint summary for %s", checkpointID)
231		commitHash, err := CreateCommit(ctx, s.repo, checkpointSubtree, parentHash, commitMsg, authorName, authorEmail)
232		if err != nil {
233			return err
234		}
235		return s.setRef(ctx, checkpointID, commitHash)
236	}
237	
238	// checkpointTree resolves a FetchingTree rooted at a checkpoint's ref commit
239	// tree (which is the checkpoint subtree itself). Returns ErrCheckpointNotFound
240	// when the ref or its commit/tree cannot be resolved.
241	func (s *gitRefsStore) checkpointTree(ctx context.Context, cid id.CheckpointID) (*FetchingTree, error) {
242		if err := ctx.Err(); err != nil {
243			return nil, err //nolint:wrapcheck // Propagating context cancellation
244		}
245		ref, err := s.resolveRefMaybeFetch(ctx, cid)
246		if err != nil {
247			if errors.Is(err, plumbing.ErrReferenceNotFound) {
248				return nil, ErrCheckpointNotFound
249			}
250			return nil, err
251		}
252		commit, err := s.repo.CommitObject(ref.Hash())
253		if err != nil {
254			// The ref resolved but its commit object doesn't — corruption/IO, not an
255			// absent checkpoint. Surface it instead of masking as "not found".
256			return nil, fmt.Errorf("read checkpoint commit %s for %s: %w", ref.Hash(), cid, err)
257		}
258		tree, err := commit.Tree()
259		if err != nil {
260			return nil, fmt.Errorf("read checkpoint tree for %s: %w", cid, err)
261		}
262		return NewFetchingTree(ctx, tree, s.repo.Storer, s.blobFetcher), nil
263	}
264	
265	// resolveRefMaybeFetch resolves a checkpoint ref, fetching it from the remote
266	// once when it is missing locally and a ref fetcher is configured (the
267	// checkpoint may have been written on another machine). It distinguishes a
268	// genuinely absent ref (returns a plumbing.ErrReferenceNotFound-wrapped error,
269	// which callers map to ErrCheckpointNotFound) from a real failure — an IO error,
270	// or a fetch that failed for network/context reasons — which is returned as-is
271	// so it is not silently swallowed as "checkpoint not found".
272	func (s *gitRefsStore) resolveRefMaybeFetch(ctx context.Context, cid id.CheckpointID) (*plumbing.Reference, error) {
273		refName, err := RefName(cid)
274		if err != nil {
275			return nil, err
276		}
277		ref, err := s.repo.Reference(refName, true)
278		if err == nil {
279			return ref, nil
280		}
281		if !errors.Is(err, plumbing.ErrReferenceNotFound) {
282			return nil, fmt.Errorf("resolve checkpoint ref %s: %w", refName, err)
283		}
284		if s.refFetcher == nil {
285			return nil, err //nolint:wrapcheck // genuinely absent; caller maps ErrReferenceNotFound to ErrCheckpointNotFound
286		}
287		if fetchErr := s.refFetcher(ctx, refName); fetchErr != nil {
288			logging.Debug(ctx, "git-refs: on-demand checkpoint ref fetch failed",
289				slog.String("ref", refName.String()), slog.String("error", fetchErr.Error()))
290			return nil, fmt.Errorf("fetch checkpoint ref %s: %w", refName, fetchErr)
291		}
292		// Re-resolve after a successful fetch. ErrReferenceNotFound here means the
293		// remote genuinely has no such checkpoint; anything else is a real error.
294		ref, err = s.repo.Reference(refName, true)
295		if err != nil {
296			return nil, err //nolint:wrapcheck // ErrReferenceNotFound (absent) or a real error; caller distinguishes via errors.Is
297		}
298		return ref, nil
299	}
300	
301	// sessionTree resolves the FetchingTree for one session within a checkpoint ref.
302	func (s *gitRefsStore) sessionTree(ctx context.Context, cid id.CheckpointID, sessionIndex int) (*FetchingTree, error) {
303		ct, err := s.checkpointTree(ctx, cid)
304		if err != nil {
305			return nil, err
306		}
307		sessionTree, err := ct.Tree(strconv.Itoa(sessionIndex))
308		if err != nil {
309			return nil, fmt.Errorf("%w: session %d not found: %w", ErrCheckpointNotFound, sessionIndex, err)
310		}
311		return sessionTree, nil
312	}
313	
314	// Read returns the checkpoint summary, or (nil, nil) when the checkpoint's ref
315	// is absent, so the contract normalizes it to ErrCheckpointNotFound.
316	func (s *gitRefsStore) Read(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
317		ct, err := s.checkpointTree(ctx, checkpointID)
318		if err != nil {
319			if errors.Is(err, ErrCheckpointNotFound) {
320				return nil, nil //nolint:nilnil // absent ref → no checkpoint; contract normalizes to ErrCheckpointNotFound
321			}
322			return nil, err
323		}
324		return readSummaryFromCheckpointTree(ct)
325	}
326	
327	func (s *gitRefsStore) ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*Metadata, error) {
328		sessionTree, err := s.sessionTree(ctx, checkpointID, sessionIndex)
329		if err != nil {
330			return nil, err
331		}
332		return readSessionMetadataFromTree(sessionTree, sessionIndex)
333	}
334	
335	func (s *gitRefsStore) ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*Metadata, string, error) {
336		sessionTree, err := s.sessionTree(ctx, checkpointID, sessionIndex)
337		if err != nil {
338			return nil, "", err
339		}
340		return readSessionMetadataAndPromptsFromTree(sessionTree, sessionIndex)
341	}
342	
343	func (s *gitRefsStore) ReadSessionPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (string, error) {
344		sessionTree, err := s.sessionTree(ctx, checkpointID, sessionIndex)
345		if err != nil {
346			return "", err
347		}
348		return readSessionPromptsFromTree(sessionTree)
349	}
350	
351	func (s *gitRefsStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
352		sessionTree, err := s.sessionTree(ctx, checkpointID, sessionIndex)
353		if err != nil {
354			return nil, err
355		}
356		return readSessionContentFromTree(ctx, sessionTree)
357	}
358	
359	// List enumerates local checkpoint refs and reads each root summary, sorted most
360	// recent first. Storage-level listing is local-refs-only for now (no remote
361	// enumeration), matching the issue's first-version scope.
362	func (s *gitRefsStore) List(ctx context.Context) ([]CheckpointInfo, error) {
363		if err := ctx.Err(); err != nil {
364			return nil, err //nolint:wrapcheck // Propagating context cancellation
365		}
366	
367		refs, err := s.repo.References()
368		if err != nil {
369			return nil, fmt.Errorf("list checkpoint refs: %w", err)
370		}
371		defer refs.Close()
372	
373		var checkpoints []CheckpointInfo
374		err = refs.ForEach(func(ref *plumbing.Reference) error {
375			cid, ok := ParseRef(ref.Name())
376			if !ok {
377				return nil
378			}
379			commit, commitErr := s.repo.CommitObject(ref.Hash())
380			if commitErr != nil {
381				return nil //nolint:nilerr // skip unreadable refs, keep listing
382			}
383			tree, treeErr := commit.Tree()
384			if treeErr != nil {
385				return nil //nolint:nilerr // skip unreadable refs, keep listing
386			}
387			checkpoints = append(checkpoints, readCommittedInfoFromCheckpointTree(cid, tree))
388			return nil
389		})
390		if err != nil {
391			return nil, fmt.Errorf("iterate checkpoint refs: %w", err)
392		}
393	
394		sortCheckpointInfosByRecency(checkpoints)
395		return checkpoints, nil
396	}
397	
398	// GetCheckpointAuthor returns the author of the checkpoint ref's tip commit (the
399	// most recent writer). Returns a zero Author when the ref is absent.
400	func (s *gitRefsStore) GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (Author, error) {
401		if err := ctx.Err(); err != nil {
402			return Author{}, err //nolint:wrapcheck // Propagating context cancellation
403		}
404		refName, err := RefName(checkpointID)
405		if err != nil {
406			return Author{}, nil //nolint:nilerr // invalid ID → unknown author
407		}
408		ref, err := s.repo.Reference(refName, true)
409		if err != nil {
410			return Author{}, nil //nolint:nilerr // no ref → unknown author
411		}
412		commit, err := s.repo.CommitObject(ref.Hash())
413		if err != nil {
414			return Author{}, nil //nolint:nilerr // unreadable → unknown author
415		}
416		return Author{Name: commit.Author.Name, Email: commit.Author.Email}, nil
417	}
